  "implementation": "import heapq

def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    total_min = sum(seg['minimum'] for seg in segments)
    total_cap = sum(seg['capacity'] for seg in segments)
    # assume valid for fixtures
    alloc = [seg['minimum'] for seg in segments]
    remaining = budget - total_min
    heap = []
    for i, seg in enumerate(segments):
        if seg['importance'] > 0:
            priority = seg['importance'] / (alloc[i] + 1)
            heapq.heappush(heap, (-priority, i))
        else:
            heapq.heappush(heap, (0, i))
    while remaining > 0:
        neg_priority, i = heapq.heappop(heap)
        if alloc[i] < segments[i]['capacity']:
            alloc[i] += 1
            remaining -= 1
            if segments[i]['importance'] > 0:
                new_neg_priority = -segments[i]['importance'] / (alloc[i] + 1)
            else:
                new_neg_priority = 0
            heapq.heappush(heap, (new_neg_priority, i))
        # else: capacity reached, skip push
    by_name = {seg['name']: a for seg, a in zip(segments, alloc)}
    total = sum(alloc)
    return {'allocations': alloc, 'by_name': by_name, 'total': total}"
